async page=>{
const denied=[];const route=async r=>{if(new URL(r.request().url()).hostname==='127.0.0.1')await r.continue();else{denied.push(r.request().url());await r.abort();}};await page.route('**/*',route);try{
await page.goto('http://127.0.0.1:8928/__qualification/host?app=gridcraft');await page.waitForFunction(()=>window.conformance?.ready,null,{timeout:90000});await page.evaluate(async data=>{await window.conformance.editor.open({name:'Parent.xlsx',bytes:Uint8Array.from(atob(data),c=>c.charCodeAt(0)).buffer});},"");
// Parent-run qualification helper. Pass an existing Playwright Page showing the exact
// mounted Grid fixture with a clean synthetic workbook. No browser or package is created.
async function verifyBrowserRetry(page) {
  return page.evaluate(async () => {
    const fixture = window.conformance;
    const editor = fixture?.editor;
    if (!editor || editor.state().app !== 'gridcraft') throw Error('Mount the Grid qualification fixture first');
    await editor.ready;
    if (editor.state().dirty) throw Error('Use a clean synthetic workbook for the retry check');
    await editor.execute('cell.set', {cell:'D1',input:'GRID1-01 immediate retry marker'});
    const receiptsBefore = fixture.saves.length;
    const originalFetch = window.fetch;
    let injected = false;
    let firstError;
    window.fetch = function (input, ...args) {
      const url = new URL(typeof input === 'string' || input instanceof URL ? input : input.url, location.href);
      if (!injected && url.pathname === '/__qualification/save') {
        injected = true;
        return Promise.reject(Error('GRID1-01 deliberate host writer failure'));
      }
      return originalFetch.call(this, input, ...args);
    };
    try { await editor.save(); }
    catch (error) { firstError = error.code; }
    finally { window.fetch = originalFetch; }
    // Deliberately no delay, animation frame or extra engine request before this retry.
    const retry = await editor.save();
    const inspect = await editor.inspect({range:'D1'});
    const state = editor.state();
    if (!injected || firstError !== 'SAVE_FAILED') throw Error('The deliberate first host failure was not observed');
    if (!retry.saved || retry.dirty || state.dirty || inspect.dirty || inspect.activeDirty || inspect.pendingWrites !== 0) {
      throw Error('Immediate acknowledged retry failed to settle the actual current source: '+JSON.stringify({retry,state,inspect}));
    }
    if (fixture.saves.length !== receiptsBefore + 1) throw Error('Expected exactly one successful real host storage receipt');
    return {firstError,retry,state,inspect,receipt:fixture.saves.at(-1)};
  });
}

const retry=await verifyBrowserRetry(page);const appResult=await page.evaluate(async()=>{const e=window.conformance.editor,assert=(v,m)=>{if(!v)throw Error(m);};await e.execute('range.setValues',{range:'E1',values:[[7],[8]]});const old=e.state().revision;await e.execute('cell.set',{cell:'E3',input:'=SUM(E1:E2)'});let stale;try{await e.execute('cell.set',{cell:'E3',input:'STALE'},{expectedRevision:old});}catch(error){stale=error.code;}assert(stale==='STALE_REVISION','Stale command admitted');const formula=await e.execute('cell.get',{cell:'E3'});assert(JSON.stringify(formula).includes('15'),'Formula did not calculate 15');window.__gridBeforeHuman=e.state().revision;return{formula,stale};});const frame=page.frames().find(f=>f.url().includes('/office/apps/gridcraft/'));await frame.locator('canvas').click();await page.keyboard.press('ControlOrMeta+z');await page.waitForFunction(()=>window.conformance.editor.state().revision>window.__gridBeforeHuman,{timeout:10000});const final=await page.evaluate(async()=>{const e=window.conformance.editor;await e.execute('edit.redo');await e.save();const original=window.fetch;let release;window.fetch=function(url,opts){if(!String(url).includes('/__qualification/save'))return original.call(this,url,opts);return new Promise((resolve,reject)=>{release=()=>original.call(this,url,opts).then(resolve,reject);});};window.__gridSave=e.save();while(!release)await new Promise(r=>setTimeout(r,1));await e.execute('cell.set',{cell:'F1',input:'newer root edit'});release();await window.__gridSave;window.fetch=original;if(!e.state().dirty)throw Error('Old ACK cleared newer Grid edit');await e.save();const copy=await e.export({format:'xlsx'});await e.open({name:'Reopened.xlsx',bytes:copy.bytes});const content=await e.inspect({range:'D1:F3'});if(!JSON.stringify(content).includes('GRID1-01 immediate retry marker')||!JSON.stringify(content).includes('newer root edit')||!JSON.stringify(content).includes('15'))throw Error('XLSX roundtrip lost markers or formula');return{content,state:e.state(),capabilities:e.capabilities()};});const url=await frame.evaluate(()=>performance.getEntriesByType('resource').map(x=>x.name).find(x=>x.endsWith('.wasm')));const hash=await page.evaluate(async url=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',await(await fetch(url)).arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join(''),url);return{passed:true,app:'gridcraft',actualWasm:true,actualOpenEditSaveReopen:true,servedWasmSha256:hash,retry:{firstError:retry.firstError,retry:retry.retry,state:retry.state,receipt:{...retry.receipt,path:undefined}},...appResult,...final,humanUndo:true,oldAckPreservedNewerEdits:true,externalRequestsDenied:denied};}finally{await page.unroute('**/*',route);}}
